14	// runResult captures one invocation of the command against a file on disk.
15	type runResult struct {
16		code   int
17		stdout string
18		stderr string
19	}
20	
21	func runWithFile(t *testing.T, content string, args ...string) runResult {
22		t.Helper()
23		dir := t.TempDir()
24		path := filepath.Join(dir, "samples.txt")
25		if content != "" {
26			if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
27				t.Fatal(err)
28			}
29		} else {
30			// An explicitly empty file is different from a missing path.
31			if err := os.WriteFile(path, nil, 0o600); err != nil {
32				t.Fatal(err)
33			}
34		}
35		full := append([]string{"--file", path}, args...)
36		var stdout, stderr bytes.Buffer
37		code := run(full, &stdout, &stderr)
38		return runResult{code, stdout.String(), stderr.String()}
39	}
40	
41	func runArgs(t *testing.T, args ...string) runResult {
42		t.Helper()
43		var stdout, stderr bytes.Buffer
44		code := run(args, &stdout, &stderr)
45		return runResult{code, stdout.String(), stderr.String()}
46	}
47	
48	func TestRunAggregatesWindows(t *testing.T) {
49		content := strings.Join([]string{
50			"0 1",
51			"500000000 2",   // same 1s window
52			"1000000000 -3", // next window
53			"   ",           // whitespace-only, skipped
54			"",              // blank, skipped
55			"1500000000 -0", // negative zero
56			"2000000000 1.5",
57		}, "\n") + "\n"
58		got := runWithFile(t, content, "--window", "1s", "windows")
59		if got.code != 0 {
60			t.Fatalf("code = %d, stderr = %q", got.code, got.stderr)
61		}
62		want := strings.Join([]string{
63			"0 2 3 1 2",
64			"1000000000 2 -3 -3 -0",
65			"2000000000 1 1.5 1.5 1.5",
66			"",
67		}, "\n")
68		if got.stdout != want {
69			t.Fatalf("stdout = %q, want %q", got.stdout, want)
70		}
71	}
72	
73	func TestRunShortestFloatFormatting(t *testing.T) {
74		// 1e20 renders "1e+20" under 'g' -1; the sum keeps whatever the
75		// floating-point addition yields, still in its shortest form.
76		content := "0 1e20\n0 150000\n"
77		got := runWithFile(t, content, "--window", "1m", "windows")
78		if got.code != 0 {
79			t.Fatalf("code = %d, stderr = %q", got.code, got.stderr)
80		}
81		if want := "0 2 1.0000000000000015e+20 150000 1e+20\n"; got.stdout != want {
82			t.Fatalf("stdout = %q, want %q", got.stdout, want)
83		}
84	}
85	
86	func TestRunNegativeWindowStart(t *testing.T) {
87		// -1.5s aligns down to -2s in a 2s window; -1s stays in [-2s, 0).
88		content := "-1500000000 4\n-1000000000 8\n"
89		got := runWithFile(t, content, "--window", "2s", "windows")
90		if got.code != 0 {
91			t.Fatalf("code = %d, stderr = %q", got.code, got.stderr)
92		}
93		if got.stdout != "-2000000000 2 12 4 8\n" {
94			t.Fatalf("stdout = %q", got.stdout)
95		}
96	}
97	
98	func TestRunExtremeTimestamp(t *testing.T) {
99		// MinInt64 aligned to a 3ns window starts at -9223372036854775809,
100		// which is outside the int64 range; the start must print exactly.
101		content := "-9223372036854775808 1\n"
102		got := runWithFile(t, content, "--window", "3ns", "windows")
103		if got.code != 0 {
104			t.Fatalf("code = %d, stderr = %q", got.code, got.stderr)
105		}
106		if !strings.HasPrefix(got.stdout, "-9223372036854775809 ") {
107			t.Fatalf("stdout = %q", got.stdout)
108		}
109	}
110	
111	func TestRunMaxTimestamp(t *testing.T) {
112		content := "9223372036854775807 1\n"
113		got := runWithFile(t, content, "--window", "1ns", "windows")
114		if got.code != 0 {
115			t.Fatalf("code = %d, stderr = %q", got.code, got.stderr)
116		}
117		if got.stdout != "9223372036854775807 1 1 1 1\n" {
118			t.Fatalf("stdout = %q", got.stdout)
119		}
120	}
121	
122	func TestRunFlagsBeforeAndAfterSubcommand(t *testing.T) {
123		content := "0 1\n"
124		got := runWithFile(t, content, "windows", "--window=1s")
125		if got.code != 0 {
126			t.Fatalf("flags after subcommand: code = %d, stderr = %q", got.code, got.stderr)
127		}
128		if got.stdout != "0 1 1 1 1\n" {
129			t.Fatalf("stdout = %q", got.stdout)
130		}
131	}
132	
133	func TestRunArgumentErrors(t *testing.T) {
134		cases := []struct {
135			name string
136			args []string
137		}{
138			{"no args", nil},
139			{"missing subcommand", []string{"--file", "x", "--window", "1s"}},
140			{"unknown subcommand", []string{"--file", "x", "--window", "1s", "rollup"}},
141			{"second positional", []string{"--file", "x", "--window", "1s", "windows", "extra"}},
