package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// runWithFiles writes each named content to its own file and runs the
// command with the given arguments, replacing every "<name>" placeholder
// with the file's path.
func runWithFiles(t *testing.T, contents map[string]string, args ...string) runResult {
	t.Helper()
	dir := t.TempDir()
	full := make([]string, 0, len(args))
	for _, a := range args {
		if content, ok := contents[a]; ok {
			path := filepath.Join(dir, a)
			if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
				t.Fatal(err)
			}
			a = path
		}
		full = append(full, a)
	}
	return runArgs(t, full...)
}

func TestRangeSelectsHalfOpenInterval(t *testing.T) {
	content := strings.Join([]string{
		"0 1",
		"500000000 2",
		"1000000000 -3",
		"1500000000 4",
		"2000000000 5",
	}, "\n") + "\n"
	files := map[string]string{"samples.txt": content}

	// [1s, 2s) keeps the windows starting at 1s; the window starting
	// exactly at --to is excluded.
	got := runWithFiles(t, files, "--file", "samples.txt", "--window", "1s",
		"range", "--from", "1000000000", "--to", "2000000000")
	if got.code != 0 {
		t.Fatalf("code = %d, stderr = %q", got.code, got.stderr)
	}
	if want := "1000000000 2 1 -3 4\n"; got.stdout != want {
		t.Fatalf("stdout = %q, want %q", got.stdout, want)
	}

	// A start inside a window selects the whole window containing it.
	got = runWithFiles(t, files, "--file", "samples.txt", "--window", "1s",
		"range", "--from", "1200000000", "--to", "1500000000")
	if got.code != 0 {
		t.Fatalf("code = %d, stderr = %q", got.code, got.stderr)
	}
	if want := "1000000000 2 1 -3 4\n"; got.stdout != want {
		t.Fatalf("stdout = %q, want %q", got.stdout, want)
	}
}

func TestRangeEmptyResultsAreNotErrors(t *testing.T) {
	files := map[string]string{"samples.txt": "0 1\n1000000000 2\n"}
	for name, endpoints := range map[string][2]string{
		"from equals to":   {"1000000000", "1000000000"},
		"from after to":    {"2000000000", "1000000000"},
		"no window inside": {"2000000000", "3000000000"},
		"before first":     {"-3000000000", "-2000000000"},
	} {
		t.Run(name, func(t *testing.T) {
			got := runWithFiles(t, files, "--file", "samples.txt", "--window", "1s",
				"range", "--from", endpoints[0], "--to", endpoints[1])
			if got.code != 0 {
				t.Fatalf("code = %d, stderr = %q", got.code, got.stderr)
			}
			if got.stdout != "" {
				t.Fatalf("stdout = %q, want empty", got.stdout)
			}
		})
	}
}

func TestRangeCoversManyWindowsInBatches(t *testing.T) {
	// More windows than one cursor batch, so iteration must advance.
	var lines []string
	for i := 0; i < 3000; i++ {
		lines = append(lines, fmt.Sprintf("%d %d", i*1000000, i))
	}
	files := map[string]string{"samples.txt": strings.Join(lines, "\n") + "\n"}
	got := runWithFiles(t, files, "--file", "samples.txt", "--window", "1ms",
		"range", "--from", "0", "--to", "3000000000")
	if got.code != 0 {
		t.Fatalf("code = %d, stderr = %q", got.code, got.stderr)
	}
	out := strings.Split(strings.TrimRight(got.stdout, "\n"), "\n")
	if len(out) != 3000 {
		t.Fatalf("got %d lines, want 3000", len(out))
	}
	if out[0] != "0 1 0 0 0" || out[2999] != "2999000000 1 2999 2999 2999" {
		t.Fatalf("first = %q, last = %q", out[0], out[2999])
	}
}

func TestRangeNegativeAndExtremeEndpoints(t *testing.T) {
	files := map[string]string{"samples.txt": "-1500000000 4\n-1000000000 8\n"}
	got := runWithFiles(t, files, "--file", "samples.txt", "--window", "2s",
		"range", "--from", "-2000000000", "--to", "0")
	if got.code != 0 {
		t.Fatalf("code = %d, stderr = %q", got.code, got.stderr)
	}
	if got.stdout != "-2000000000 2 12 4 8\n" {
		t.Fatalf("stdout = %q", got.stdout)
	}

	files = map[string]string{"samples.txt": "9223372036854775807 1\n"}
	got = runWithFiles(t, files, "--file", "samples.txt", "--window", "1ns",
		"range", "--from", "9223372036854775807", "--to", "-9223372036854775808")
	if got.code != 0 || got.stdout != "" {
		t.Fatalf("backwards extreme interval: code = %d, stdout = %q", got.code, got.stdout)
	}
}

func TestRangeArgumentErrors(t *testing.T) {
	files := map[string]string{"samples.txt": "0 1\n"}
	cases := []struct {
		name string
		args []string
	}{
		{"missing from", []string{"--file", "samples.txt", "--window", "1s", "range", "--to", "1"}},
		{"missing to", []string{"--file", "samples.txt", "--window", "1s", "range", "--from", "1"}},
		{"bad from", []string{"--file", "samples.txt", "--window", "1s", "range", "--from", "x", "--to", "1"}},
		{"bad to", []string{"--file", "samples.txt", "--window", "1s", "range", "--from", "1", "--to", "1.5"}},
		{"from out of range", []string{"--file", "samples.txt", "--window", "1s", "range", "--from", "9223372036854775808", "--to", "1"}},
		{"extra positional", []string{"--file", "samples.txt", "--window", "1s", "range", "--from", "1", "--to", "2", "extra"}},
		{"unknown flag", []string{"--file", "samples.txt", "--window", "1s", "range", "--from", "1", "--to", "2", "--step", "3"}},
		{"two files", []string{"--file", "samples.txt", "--file", "samples.txt", "--window", "1s", "range", "--from", "1", "--to", "2"}},
		{"from on windows", []string{"--file", "samples.txt", "--window", "1s", "windows", "--from", "1"}},
		{"from on merge", []string{"--file", "samples.txt", "--file", "samples.txt", "--window", "1s", "merge", "--from", "1", "--to", "2"}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := runWithFiles(t, files, tc.args...)
			if got.code != 2 {
				t.Fatalf("code = %d, want 2; stderr = %q", got.code, got.stderr)
			}
			if !strings.HasPrefix(got.stderr, "rollupctl: ") {
				t.Fatalf("stderr = %q, want rollupctl: prefix", got.stderr)
			}
			if strings.Count(strings.TrimRight(got.stderr, "\n"), "\n") != 0 {
				t.Fatalf("stderr must be one line, got %q", got.stderr)
			}
			if got.stdout != "" {
				t.Fatalf("stdout must be empty, got %q", got.stdout)
			}
		})
	}
}

func TestRangeFileAndContentErrors(t *testing.T) {
	dir := t.TempDir()
	missing := filepath.Join(dir, "does-not-exist")
	got := runArgs(t, "--file", missing, "--window", "1s", "range", "--from", "0", "--to", "1")
	if got.code != 3 {
		t.Fatalf("missing file: code = %d, stderr = %q", got.code, got.stderr)
	}
	got = runArgs(t, "--file", dir, "--window", "1s", "range", "--from", "0", "--to", "1")
	if got.code != 3 {
		t.Fatalf("directory: code = %d, stderr = %q", got.code, got.stderr)
	}

	files := map[string]string{"bad.txt": "0 1\n50 2\n30 3\n"}
	got = runWithFiles(t, files, "--file", "bad.txt", "--window", "1s", "range", "--from", "0", "--to", "100")
	if got.code != 4 || got.stdout != "" {
		t.Fatalf("out of order: code = %d, stdout = %q, stderr = %q", got.code, got.stdout, got.stderr)
	}

	files = map[string]string{"empty.txt": "\n  \n"}
	got = runWithFiles(t, files, "--file", "empty.txt", "--window", "1s", "range", "--from", "0", "--to", "1")
	if got.code != 4 || !strings.Contains(got.stderr, ":0:") {
		t.Fatalf("blank file: code = %d, stderr = %q", got.code, got.stderr)
	}
}

func TestMergeCombinesWindows(t *testing.T) {
	files := map[string]string{
		"a.txt": "0 1\n500000000 2\n2000000000 5\n",
		"b.txt": "500000000 10\n1000000000 -3\n",
	}
	got := runWithFiles(t, files, "--file", "a.txt", "--file", "b.txt", "--window", "1s", "merge")
	if got.code != 0 {
		t.Fatalf("code = %d, stderr = %q", got.code, got.stderr)
	}
	want := strings.Join([]string{
		"0 3 13 1 10",
		"1000000000 1 -3 -3 -3",
		"2000000000 1 5 5 5",
		"",
	}, "\n")
	if got.stdout != want {
		t.Fatalf("stdout = %q, want %q", got.stdout, want)
	}
}

func TestMergeSameFileTwice(t *testing.T) {
	files := map[string]string{"a.txt": "0 2\n"}
	got := runWithFiles(t, files, "--file", "a.txt", "--file", "a.txt", "--window", "1s", "merge")
	if got.code != 0 {
		t.Fatalf("code = %d, stderr = %q", got.code, got.stderr)
	}
	if got.stdout != "0 2 4 2 2\n" {
		t.Fatalf("stdout = %q", got.stdout)
	}
}

func TestMergeArgumentErrors(t *testing.T) {
	files := map[string]string{"a.txt": "0 1\n", "b.txt": "0 2\n", "c.txt": "0 3\n"}
	cases := []struct {
		name string
		args []string
	}{
		{"one file", []string{"--file", "a.txt", "--window", "1s", "merge"}},
		{"three files", []string{"--file", "a.txt", "--file", "b.txt", "--file", "c.txt", "--window", "1s", "merge"}},
		{"no file", []string{"--window", "1s", "merge"}},
		{"missing window", []string{"--file", "a.txt", "--file", "b.txt", "merge"}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := runWithFiles(t, files, tc.args...)
			if got.code != 2 {
				t.Fatalf("code = %d, want 2; stderr = %q", got.code, got.stderr)
			}
			if got.stdout != "" {
				t.Fatalf("stdout must be empty, got %q", got.stdout)
			}
		})
	}
}

func TestMergeFileAndContentErrors(t *testing.T) {
	dir := t.TempDir()
	missing := filepath.Join(dir, "does-not-exist")
	good := filepath.Join(dir, "good.txt")
	if err := os.WriteFile(good, []byte("0 1\n"), 0o600); err != nil {
		t.Fatal(err)
	}

	got := runArgs(t, "--file", good, "--file", missing, "--window", "1s", "merge")
	if got.code != 3 || got.stdout != "" {
		t.Fatalf("missing second file: code = %d, stdout = %q", got.code, got.stdout)
	}
	got = runArgs(t, "--file", missing, "--file", good, "--window", "1s", "merge")
	if got.code != 3 || got.stdout != "" {
		t.Fatalf("missing first file: code = %d, stdout = %q", got.code, got.stdout)
	}

	// A content problem in either file rejects the whole batch: no window
	// lines from the good file may leak out.
	files := map[string]string{
		"good.txt": "0 1\n1000000000 2\n",
		"bad.txt":  "0 1\n0 NaN\n",
	}
	got = runWithFiles(t, files, "--file", "good.txt", "--file", "bad.txt", "--window", "1s", "merge")
	if got.code != 4 || got.stdout != "" {
		t.Fatalf("bad second file: code = %d, stdout = %q, stderr = %q", got.code, got.stdout, got.stderr)
	}
	got = runWithFiles(t, files, "--file", "bad.txt", "--file", "good.txt", "--window", "1s", "merge")
	if got.code != 4 || got.stdout != "" {
		t.Fatalf("bad first file: code = %d, stdout = %q, stderr = %q", got.code, got.stdout, got.stderr)
	}

	files = map[string]string{"good.txt": "0 1\n", "empty.txt": ""}
	got = runWithFiles(t, files, "--file", "good.txt", "--file", "empty.txt", "--window", "1s", "merge")
	if got.code != 4 || !strings.Contains(got.stderr, ":0:") || got.stdout != "" {
		t.Fatalf("empty second file: code = %d, stdout = %q, stderr = %q", got.code, got.stdout, got.stderr)
	}
}

input.content:
// Command rollupctl reads timestamped samples from a file, files them into
// fixed windows aligned to the Unix epoch, and prints, one per line, each
// window's start, count, sum, minimum, and maximum.
//
// Usage:
//
//	rollupctl --file <path> --window <duration> windows
//	rollupctl --file <path> --window <duration> --from <ns> --to <ns> range
//	rollupctl --file <path> --file <path> --window <duration> merge
//
// The input file holds one sample per line: an integer number of
// nanoseconds since the epoch, whitespace, then a floating-point value.
// Blank and whitespace-only lines carry no sample. Samples must arrive in
// non-decreasing time order.
//
// windows prints every window of one file. range prints only the windows
// of one file that overlap the half-open interval [--from, --to), with both
// endpoints given as signed integer nanoseconds since the epoch; an empty,
// backwards, or unmatched interval prints nothing. merge aggregates two
// files that share the window size and prints their windows combined,
// folding windows that start at the same instant into one line.
//
// Exit codes: 0 success, 2 bad command-line arguments, 3 an input file
// does not exist or is a directory, 4 an input file's contents are invalid
// or the two merge inputs cannot be combined.
package main

import (
	"bufio"
	"errors"
	"fmt"
	"io"
	"math"
	"math/big"
	"os"
	"strconv"
	"strings"
	"time"

	"github.com/Hulalalalalalalalalalala/metric-rollup/rollup"
)

// maxLineBytes is the longest accepted physical input line, excluding the
// line terminator.
const maxLineBytes = 1024

// rangeBatchSize is how many windows one cursor Next call hands the range
// subcommand, so a hundred-thousand-window interval is emitted in batches
// instead of being materialized as one whole listing.
const rangeBatchSize = 1024

func main() {
	os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
}

// command holds one parsed command line: the subcommand and the flag
// values it runs with.
type command struct {
	sub            string
	files          []string
	window         string
	from, to       string
	hasFrom, hasTo bool
}

// run parses args, reads the input file or files, and writes the window
// listing. It returns the process exit code; every diagnostic is a single
// line on stderr prefixed with "rollupctl: ".
func run(args []string, stdout, stderr io.Writer) int {
	cmd, ok := parseArgs(args, stderr)
	if !ok {
		return 2
	}
	d, err := time.ParseDuration(cmd.window)
	if err != nil {
		argError(stderr, "invalid --window %q: %v", cmd.window, err)
		return 2
	}
	if d <= 0 {
		argError(stderr, "--window must be positive, got %s", d)
		return 2
	}

	switch cmd.sub {
	case "range":
		from, err := strconv.ParseInt(cmd.from, 10, 64)
		if err != nil {
			argError(stderr, "invalid --from %q: %v", cmd.from, err)
			return 2
		}
		to, err := strconv.ParseInt(cmd.to, 10, 64)
		if err != nil {
			argError(stderr, "invalid --to %q: %v", cmd.to, err)
			return 2
		}
		return runRange(cmd.files[0], d, from, to, stdout, stderr)
	case "merge":
		return runMerge(cmd.files[0], cmd.files[1], d, stdout, stderr)
	default:
		return runWindows(cmd.files[0], d, stdout, stderr)
	}
}

// runWindows prints every window of one file, in time order.
func runWindows(path string, d time.Duration, stdout, stderr io.Writer) int {
	roller, code := ingestFile(path, d, stderr)
	if code != 0 {
		return code
	}
	out := bufio.NewWriter(stdout)
	writeWindows(out, roller.Windows())
	return flushOutput(out, stderr)
}

// runRange prints the windows overlapping the half-open interval
// [from, to), in time order, advancing through an existing-API cursor one
// batch at a time. The interval endpoints are attributed to windows by the
// roller's own half-open rule. Equal endpoints, a backwards interval, and
// an interval no window overlaps are not errors and print nothing.
func runRange(path string, d time.Duration, from, to int64, stdout, stderr io.Writer) int {
	roller, code := ingestFile(path, d, stderr)
	if code != 0 {
		return code
	}
	out := bufio.NewWriter(stdout)
	cursor := roller.Cursor(time.Unix(0, from).UTC(), time.Unix(0, to).UTC())
	for {
		batch := cursor.Next(rangeBatchSize)
		if len(batch) == 0 {
			break
		}
		writeWindows(out, batch)
	}
	return flushOutput(out, stderr)
}

// runMerge aggregates two files with one window size and prints the
// combined listing. Both files are ingested before any window line is
// written, so a problem in either file rejects the whole batch: no line is
// printed on any failure.
func runMerge(pathA, pathB string, d time.Duration, stdout, stderr io.Writer) int {
	rollerA, code := ingestFile(pathA, d, stderr)
	if code != 0 {
		return code
	}
	rollerB, code := ingestFile(pathB, d, stderr)
	if code != 0 {
		return code
	}
	// With one --window both rollers necessarily share the width, but keep
	// the existing mismatch contract: if they ever did not, refuse the
	// whole batch in one diagnostic naming both files.
	if err := rollerA.Merge(rollerB); err != nil {
		fmt.Fprintf(stderr, "rollupctl: %s and %s: %v\n", pathA, pathB, err)
		return 4
	}
	out := bufio.NewWriter(stdout)
	writeWindows(out, rollerA.Windows())
	return flushOutput(out, stderr)
}

// ingestFile opens one input file and streams its samples into a fresh
// roller. It returns exit code 3 with one diagnostic when the file is
// missing or a directory, and delegates invalid contents to ingest.
func ingestFile(path string, d time.Duration, stderr io.Writer) (*rollup.Roller, int) {
	info, err := os.Stat(path)
	if err != nil {
		fmt.Fprintf(stderr, "rollupctl: %s\n", err)
		return nil, 3
	}
	if info.IsDir() {
		fmt.Fprintf(stderr, "rollupctl: %s: is a directory\n", path)
		return nil, 3
	}
	f, err := os.Open(path)
	if err != nil {
		fmt.Fprintf(stderr, "rollupctl: %s\n", err)
		return nil, 3
	}
	roller, code := ingest(f, path, d, stderr)
	f.Close()
	if code != 0 {
		return nil, code
	}
	return roller, 0
}

// writeWindows prints windows one line each in the existing window-output
// shape: start, count, sum, minimum, maximum.
func writeWindows(out *bufio.Writer, ws []rollup.Window) {
	for _, w := range ws {
		fmt.Fprintf(out, "%s %d %s %s %s\n",
			unixNanoText(w.Start), w.Count,
			formatFloat(w.Sum), formatFloat(w.Min), formatFloat(w.Max))
	}
}

// flushOutput flushes buffered output; a write failure is exit code 1.
func flushOutput(out *bufio.Writer, stderr io.Writer) int {
	if err := out.Flush(); err != nil {
		fmt.Fprintf(stderr, "rollupctl: %s\n", err)
		return 1
	}
	return 0
}

// argError writes one command-line usage diagnostic.
func argError(stderr io.Writer, format string, a ...any) {
	fmt.Fprintf(stderr, "rollupctl: "+format+"\n", a...)
}

// parseArgs extracts the subcommand and its flags. The subcommand is
// windows, range, or merge. windows and range take exactly one --file,
// merge exactly two; range additionally requires --from and --to, and no
// subcommand accepts the other's flags. Flags may stand on either side of
// the subcommand, Go-style: --name value, --name=value, with one or two
// leading dashes.
func parseArgs(args []string, stderr io.Writer) (command, bool) {
	fail := func(format string, a ...any) (command, bool) {
		argError(stderr, format, a...)
		return command{}, false
	}
	var cmd command
	sub := ""
	flagsEnded := false
	for i := 0; i < len(args); i++ {
		a := args[i]
		if !flagsEnded && a == "--" {
			flagsEnded = true
			continue
		}
		if flagsEnded || !strings.HasPrefix(a, "-") || a == "-" {
			if sub != "" || (a != "windows" && a != "range" && a != "merge") {
				return fail("unexpected argument %q", a)
			}
			sub = a
			continue
		}
		name := a[1:]
		if strings.HasPrefix(name, "-") {
			name = name[1:]
		}
		value := ""
		inline := false
		if k := strings.IndexByte(name, '='); k >= 0 {
			value = name[k+1:]
			name = name[:k]
			inline = true
		}
		switch name {
		case "file", "window", "from", "to":
			if !inline {
				i++
				if i >= len(args) {
					return fail("flag --%s needs a value", name)
				}
				value = args[i]
			}
			if value == "" {
				return fail("flag --%s needs a value", name)
			}
			switch name {
			case "file":
				cmd.files = append(cmd.files, value)
			case "window":
				cmd.window = value
			case "from":
				cmd.from, cmd.hasFrom = value, true
			case "to":
				cmd.to, cmd.hasTo = value, true
			}
		default:
			return fail("unexpected argument %q", a)
		}
	}
	cmd.sub = sub
	if sub == "" {
		return fail("expected a subcommand: windows, range, or merge")
	}
	if cmd.window == "" {
		return fail("--window is required")
	}
	switch sub {
	case "merge":
		if cmd.hasFrom || cmd.hasTo {
			return fail("--from and --to are only valid with the range subcommand")
		}
		if len(cmd.files) != 2 {
			return fail("merge requires exactly two --file arguments, got %d", len(cmd.files))
		}
	case "range":
		if len(cmd.files) != 1 {
			return fail("range requires exactly one --file, got %d", len(cmd.files))
		}
		if !cmd.hasFrom {
			return fail("--from is required")
		}
		if !cmd.hasTo {
			return fail("--to is required")
		}
	default: // windows
